<?php
declare(strict_types=1); require_once __DIR__.'/../config.php'; header('Content-Type: application/json; charset=utf-8');
function ym($v,$fallback){$v=preg_replace('/[^0-9-]/','',(string)$v);return preg_match('/^\d{4}-\d{2}$/',$v)?$v:$fallback;}
try{$a=ym($_POST['bulan_awal']??'',date('Y-m'));$b=ym($_POST['bulan_akhir']??'',date('Y-m'));if($a>$b)[$a,$b]=[$b,$a];$labels=[];$cur=DateTimeImmutable::createFromFormat('!Y-m-d',$a.'-01');$end=DateTimeImmutable::createFromFormat('!Y-m-d',$b.'-01');while($cur<=$end){$labels[]=$cur->format('Y-m');$cur=$cur->modify('+1 month');}$out=['labels'=>$labels,'ralan'=>[],'ranap'=>[],'total'=>[]];foreach(['ralan','ranap'] as $j){$vals=[];foreach($labels as $mo){$s=$mo.'-01';$e=(new DateTimeImmutable($s))->modify('+1 month')->modify('-1 day')->format('Y-m-d');$date=$j==='ralan'?"rp.tgl_registrasi BETWEEN '$s' AND '$e'":"dpo.tgl_perawatan BETWEEN '$s' AND '$e'";$join="INNER JOIN resep_obat ro ON ro.no_rawat=dpo.no_rawat AND ro.tgl_perawatan=dpo.tgl_perawatan AND ro.jam=dpo.jam ".($j==='ralan'?"INNER JOIN reg_periksa rp ON rp.no_rawat=dpo.no_rawat":"");$amount="CASE WHEN EXISTS (SELECT 1 FROM detail_obat_racikan dor WHERE dor.no_rawat=dpo.no_rawat AND dor.tgl_perawatan=dpo.tgl_perawatan AND dor.jam=dpo.jam AND dor.kode_brng=dpo.kode_brng) THEN CEIL(dpo.jml)*dpo.biaya_obat ELSE dpo.jml*dpo.biaya_obat END";$q="SELECT COALESCE(SUM($amount),0) n FROM detail_pemberian_obat dpo $join INNER JOIN databarang db ON db.kode_brng=dpo.kode_brng WHERE dpo.status='".($j==='ralan'?'Ralan':'Ranap')."' AND $date AND (db.kode_kategori NOT IN ('K01','K02','K04','K05') OR TRIM(COALESCE(db.kode_golongan,'')) IN ('','-','G01'))";$vals[]=(float)(fetch_assoc(query($q))['n']??0);} $out[$j]=$vals;}foreach($labels as $i=>$x)$out['total'][$i]=$out['ralan'][$i]+$out['ranap'][$i];echo json_encode(['ok'=>true,'data'=>$out]);}catch(Throwable $e){http_response_code(500);echo json_encode(['ok'=>false,'message'=>'Gagal mengambil chart rekap obat.']);}

